<script setup lang="ts">
import {ref,onUnmounted} from 'vue';
import {familyHeaders} from '../platform/familyTransport';
interface Row {category:string;started:number;completed:number;inFlight:number;errors:number;durationBuckets:Record<string,number>;usage?:{status:string;reportedCalls:number;promptTokens?:number;completionTokens?:number;totalTokens?:number}|null}
const data=ref<{startedAt:string;uptimeSeconds:number;storage:string;api:Row[];providers:Row[]}|null>(null),busy=ref(false),error=ref('');
const names:Record<string,string>={expansion_llm:'卡片扩写模型',report_llm:'报告说明模型',speech_tts:'远端语音合成',expansions:'卡片扩写',speech:'语音请求',reports:'报告请求',accounts:'账户',families:'家庭',sync:'云同步',assets:'图片资源',billing:'账单',support:'问题支持',resources:'公共资源',operations:'运营操作'};
const durations:Record<string,string>={lt_100ms:'少于100毫秒','100ms_to_500ms':'100–500毫秒','500ms_to_2s':'500毫秒–2秒','2s_to_10s':'2–10秒','10s_to_30s':'10–30秒',gte_30s:'30秒及以上'};
let generation=0,disposed=false,request:UniApp.RequestTask|null=null;
onUnmounted(()=>{disposed=true;generation++;request?.abort();});
async function load(){if(busy.value)return;const token=++generation;busy.value=true;error.value='';try{const result=await new Promise<NonNullable<typeof data.value>>((resolve,reject)=>{request=uni.request({url:`${import.meta.env.VITE_API_BASE_URL?.replace(/\/$/,'')||''}/api/v1/operations/metrics`,withCredentials:true,header:familyHeaders(),success:r=>{if(r.statusCode>=200&&r.statusCode<300)resolve(r.data as NonNullable<typeof data.value>);else reject(new Error((r.data as {message?:string})?.message||'指标服务未开启或没有运营权限'));},fail:()=>reject(new Error('无法连接指标服务'))});});if(token===generation&&!disposed)data.value=result;}catch(e){if(token===generation&&!disposed){data.value=null;error.value=e instanceof Error?e.message:'指标读取失败';}}finally{if(token===generation&&!disposed)busy.value=false;}}
</script>
<template><view class="service-metrics"><text class="section-title">服务运行指标</text><text class="modal-copy">仅授权运营账户可查看。计数按当前服务进程采集，重启清零；不包含姓名、卡片文字、请求正文或密钥。</text><button role="button" tabindex="0" class="outline-button" :disabled="busy" @click="load">查看服务状态与指标</button><text v-if="error" role="alert" class="error-copy">{{error}}</text><template v-if="data"><text>本进程已运行 {{Math.floor(data.uptimeSeconds/60)}} 分钟</text><text class="modal-copy">供应商实际费用未接入账单，金额未知。Token 仅统计供应商明确返回的用量，缺失用量不计为零。</text><view v-for="row in [...data.providers,...data.api]" :key="`${row.category}:${row.usage?'provider':'api'}`" class="metric-row"><text>{{names[row.category]||row.category}}</text><text>开始 {{row.started}} · 完成 {{row.completed}} · 在途 {{row.inFlight}} · 错误 {{row.errors}}</text><text v-if="row.usage">用量覆盖 {{row.usage.reportedCalls}} 次调用 · {{row.usage.status==='unknown'?'供应商未提供用量':`报告 Token ${row.usage.totalTokens??'未提供'}`}}</text><view v-for="(count,key) in row.durationBuckets" :key="key"><text>{{durations[key]||key}}：{{count}} 次</text></view></view></template></view></template>
<style scoped>.service-metrics{display:flex;flex-direction:column;gap:16px;margin-top:20px}.metric-row{display:flex;flex-direction:column;gap:8px;border:1px solid #e0e6ef;border-radius:8px;padding:14px;font-size:14px}</style>
